export function isFinalPublished(args,result) {
 if(args?.final!==true || result?.isError!==false || result?.content?.length!==1 || result.content[0].type!=='text')return false;
 try {
  const receipt=JSON.parse(result.content[0].text);
  return receipt.state==='published' && typeof receipt.messageId==='string' && receipt.messageId.length>0 && Number.isSafeInteger(receipt.roomSeq) && receipt.roomSeq>0;
 } catch{return false;}
}
